  const statuses = { file: "通常ファイル", deleted: "削除済み", symlink: "シンボリックリンク", unreadable: "読み取り不可", error: "読み取りエラー", binary: "バイナリ", directory: "ディレクトリ", other: "特殊ファイル" };
  const statusLabel = (status) => statuses[status] || status || "ファイル";
