    $("hash-alert-summary").textContent = [mismatch ? `不一致 ${mismatch} 件` : "", missing ? `未照合 ${missing} 件` : "", unattached ? `対象外の解説 ${unattached} 件` : "", !mismatch && !missing && !unattached ? `確認事項 ${warnings.length} 件` : ""].filter(Boolean).join(" · ");
