.comment-diagram{margin:17px 0 0;padding-top:14px;border-top:1px solid var(--line)}.diagram-title{display:block;font-size:11px;color:var(--ink)}.diagram-description{font-size:11px;line-height:1.8;margin:5px 0 11px;overflow-wrap:anywhere}.diagram-image-frame{overflow:auto;background:#fff;border:1px solid var(--line);border-radius:4px}.comment-diagram-image{display:block;width:100%;height:auto}.diagram-enlarge{display:block;margin:7px 0 0 auto}.diagram-error{padding:12px;margin:0;font-size:11px;line-height:1.8;color:#956648;background:#fff8ed}
.diagram-dialog{width:calc(100% - 32px);max-width:1200px;max-height:calc(100dvh - 40px);overflow:auto;padding:24px;border:1px solid #d2dfc9;border-radius:12px;color:var(--ink);background:var(--paper);box-shadow:0 18px 90px #0e251e3b}.diagram-dialog::backdrop{background:#162b2399}.diagram-dialog-hint{font-size:11px;color:var(--muted)}.diagram-dialog .comment-diagram{margin:0;border:0;padding:0}.diagram-dialog .comment-diagram-image{min-width:640px}.diagram-dialog .dialog-header{position:sticky;top:-24px;padding:10px 0;background:var(--paper);z-index:1}.diagram-dialog .dialog-header h2{margin:0}.diagram-dialog .icon-button{flex-shrink:0}
@media print{.mobile-tree-toggle,.file-sidebar,.code-toolbar,.code-footer,.detail-footer,.sync-toggle,.ask-line,.question-dialog,.diagram-dialog,.diagram-enlarge{display:none!important}.workspace{display:block;height:auto;overflow:visible}.main-panel,.detail-panel,.code-view,.code-scroll,.detail-scroll,.overview-view{height:auto;max-height:none;overflow:visible}.code-text{white-space:pre-wrap;overflow-wrap:anywhere}.code-rows{width:100%}.code-row{break-inside:avoid}.comment-card{break-inside:avoid}.panel-toolbar{min-height:0;padding:15px 0}.detail-panel{border:0}.line-number{color:#777}.code-row{font-size:8px}.comments-view{padding:0}.diff-summary{max-height:none;overflow:visible}}
